import numpy as np
WQ=W['W_Q']; WK=W['W_K']; WV=W['W_V']; WO=W['W_O']
W_in=W['W_in']; W_out=W['W_out']; W_U=W['W_U']
WE=W['W_E']; Wpos=W['W_pos']
A=acts(X)
def emb(i=None):
    return WE[X[:,0]]+Wpos[0], WE[X[:,1]]+Wpos[1], WE[X[:,2]]+Wpos[2]
def attn_fwd(e0,e1,e2):
    outs=[]
    for h in range(4):
        q=e2@WQ[h]; k0=e0@WK[h]; k1=e1@WK[h]; k2=e2@WK[h]
        s=np.stack([q@k0.T if False else (q*k0).sum(1),(q*k1).sum(1),(q*k2).sum(1)],1)/np.sqrt(32)
        s=s-s.max(1,keepdims=True); w=np.exp(s); w/=w.sum(1,keepdims=True)
        v0=e0@WV[h]; v1=e1@WV[h]; v2=e2@WV[h]
        outs.append((w[:,0:1]*v0+w[:,1:2]*v1+w[:,2:3]*v2)@WO[h])
    return sum(outs)
e0,e1,e2=emb()
rm=e2+attn_fwd(e0,e1,e2)
print("resid_mid check", np.abs(rm-A['resid_mid']).max())
def tail_full(h):
    pre=h@W_in; post=np.maximum(pre,0); mo=post@W_out; rp=h+mo
    return pre,mo,rp,rp@W_U
def end_at_emb(e0=None,e1=None):
    return tail_full(e2+attn_fwd(e0,e1,e2))
def end_at_mid(h): return tail_full(h)
def end_at_pre(pre, h): return tail_full(h) [0] if False else (lambda post: (h+post@W_out)@W_U)(np.maximum(pre,0))
def end_at_post(post,h): return (h+post@W_out)@W_U
